// Decode parses a TOML 1.0 document into tables, arrays, and tagged scalar values.
func Decode(document string) (Object, error) {
	if !utf8.ValidString(document) {
		return nil, fmt.Errorf("invalid UTF-8")
	}
	if strings.Contains(strings.ReplaceAll(document, "\r\n", ""), "\r") {
		return nil, fmt.Errorf("invalid line ending")
	}
	document = strings.ReplaceAll(document, "\r\n", "\n")
	if err := validateDocumentControls(document); err != nil {
		return nil, err
	}
	root := Object{}
	current := root
	declared := map[string]bool{}
	staticArrays := map[string]bool{}
	lines, err := statements(document)
	if err != nil {
		return nil, err
	}
	for n, raw := range lines {
		line := strings.TrimSpace(raw)
		if line == "" {
			continue
		}
		if strings.HasPrefix(line, "[[") && strings.HasSuffix(line, "]]") {
			path, err := parseKey(line[2 : len(line)-2])
			if err != nil {
				return nil, lineErr(n, err)
			}
			name := strings.Join(path, ".")
			if staticArrays[name] {
				return nil, lineErr(n, fmt.Errorf("static array cannot be an array of tables"))
			}
			parent, leaf, err := ensureParent(root, path)
			if err != nil {
				return nil, lineErr(n, err)
			}
			arr, ok := parent[leaf].([]any)
			if !ok {
				arr = []any{}
				parent[leaf] = arr
			}
			obj := Object{}
			arr = append(arr, obj)
			parent[leaf] = arr
			current = obj
			declared[strings.Join(path, ".")] = true
			continue
		}
		if strings.HasPrefix(line, "[") && strings.HasSuffix(line, "]") {
			path, err := parseKey(line[1 : len(line)-1])
			if err != nil {
				return nil, lineErr(n, err)
			}
			for i := 1; i < len(path); i++ {
				if staticArrays[strings.Join(path[:i], ".")] {
					return nil, lineErr(n, fmt.Errorf("static array cannot be extended"))
				}
			}
			obj, err := ensureTable(root, path, declared)
			if err != nil {
				return nil, lineErr(n, err)
			}
			current = obj
			continue
		}
		pos, err := assignmentEquals(line)
		if err != nil {
			return nil, lineErr(n, err)
		}
		key, err := parseKey(line[:pos])
		if err != nil {
			return nil, lineErr(n, err)
		}
		if len(key) == 0 {
			return nil, lineErr(n, fmt.Errorf("empty key"))
		}
		value, err := parseValue(strings.TrimSpace(line[pos+1:]))
		if err != nil {
			return nil, lineErr(n, err)
		}
		target := current
		for _, part := range key[:len(key)-1] {
			next, ok := target[part].(Object)
			if !ok {
				if target[part] != nil {
					return nil, lineErr(n, fmt.Errorf("key %q is not a table", part))
				}
				next = Object{}
				target[part] = next
			}
			target = next
		}
		leaf := key[len(key)-1]
		if _, exists := target[leaf]; exists {
			return nil, lineErr(n, fmt.Errorf("duplicate key %q", leaf))
		}
		target[leaf] = value
		if _, ok := value.([]any); ok {
			staticArrays[strings.Join(key, ".")] = true
		}
	}
	return root, nil
}

func validateDocumentControls(s string) error {
	for _, r := range s {
		if r == '\t' || r == '\n' || r == '\r' {
			continue
		}
		if unicode.IsSpace(r) && r != ' ' {
			return fmt.Errorf("invalid whitespace character")
		}
		if r < 0x20 || r == 0x7f {
			return fmt.Errorf("prohibited control character")
		}
	}
	return nil
}

func lineErr(n int, err error) error { return fmt.Errorf("line %d: %w", n+1, err) }

func statements(s string) ([]string, error) {
	var out []string
	start, depth := 0, 0
	quote := byte(0)
	triple := false
	for i := 0; i < len(s); i++ {
		c := s[i]
		if quote == 0 && c == '#' {
			for i < len(s) && s[i] != '\n' {
				i++
			}
			if i == len(s) {
				break
			}
			c = s[i]
		}
		if quote != 0 {
			if triple {
				if c == quote && i+2 < len(s) && s[i+1] == quote && s[i+2] == quote && (quote == '\'' || !escapedAt(s, i)) {
					run := 3
					for i+run < len(s) && s[i+run] == quote {
						run++
					}
					i += run - 1
					quote, triple = 0, false
				}
			} else if c == quote && (quote == '\'' || !escapedAt(s, i)) {
				quote = 0
			}
			continue
		}
		if c == '"' || c == '\'' {
			quote = c
			if i+2 < len(s) && s[i+1] == c && s[i+2] == c {
				triple = true
				i += 2
			}
			continue
		}
		if c == '[' || c == '{' {
			depth++
		}
		if c == ']' || c == '}' {
			depth--
			if depth < 0 {
				return nil, fmt.Errorf("unexpected closing delimiter")
			}
		}
		if c == '\n' && depth == 0 {
			out = append(out, stripComment(s[start:i]))
			start = i + 1
		}
	}
	if quote != 0 || depth != 0 {
		return nil, fmt.Errorf("unterminated value")
	}
	out = append(out, stripComment(s[start:]))
	return out, nil
}

func escapedAt(s string, i int) bool {
	count := 0
	for i > 0 && s[i-1] == '\\' {
		count++
		i--
	}
	return count%2 == 1
}

func stripComment(s string) string {
	quote := byte(0)
	triple := false
	escaped := false
	var out strings.Builder
	for i := 0; i < len(s); i++ {
		c := s[i]
		if quote != 0 {
			if triple {
				if c == quote && i+2 < len(s) && s[i+1] == quote && s[i+2] == quote && (quote == '\'' || !escapedAt(s, i)) {
					out.WriteString(s[i : i+3])
					i += 2
					quote, triple = 0, false
					continue
				}
				out.WriteByte(c)
				continue
			}
			if quote == '"' && escaped {
				escaped = false
				out.WriteByte(c)
				continue
			}
			if quote == '"' && c == '\\' {
				escaped = true
				out.WriteByte(c)
				continue
			}
			if c == quote {
				quote = 0
			}
			out.WriteByte(c)
			continue
		}
		if c == '"' || c == '\'' {
			quote = c
			if i+2 < len(s) && s[i+1] == c && s[i+2] == c {
				triple = true
				out.WriteString(s[i : i+3])
				i += 2
				continue
			}
		}
		if c == '#' {
			for i < len(s) && s[i] != '\n' {
				i++
			}
			if i < len(s) {
				out.WriteByte('\n')
			}
			continue
		}
		out.WriteByte(c)
	}
	return out.String()
package toml

import (
	"encoding/json"
	"fmt"
)

// Kind identifies the TOML type represented by a Value.
type Kind string

const (
	String        Kind = "string"
	Integer       Kind = "integer"
	Float         Kind = "float"
	Bool          Kind = "bool"
	Datetime      Kind = "datetime"
	DatetimeLocal Kind = "datetime-local"
	DateLocal     Kind = "date-local"
	TimeLocal     Kind = "time-local"
)

// Value is a scalar TOML value. Lexeme is retained as supplied by the parser
// so integer values never pass through floating-point representation.
type Value struct {
	Kind   Kind
	Lexeme string
}

// Object is the internal representation of a TOML table or array.
type Object map[string]any

// Tagged returns the JSON-compatible tagged representation of v.
func Tagged(v any) (any, error) {
	switch value := v.(type) {
	case Value:
		return struct {
			Type  Kind   `json:"type"`
			Value string `json:"value"`
		}{value.Kind, value.Lexeme}, nil
	case Object:
		result := make(map[string]any, len(value))
		for key, item := range value {
			encoded, err := Tagged(item)
			if err != nil {
				return nil, fmt.Errorf("encode %q: %w", key, err)
			}
			result[key] = encoded
		}
		return result, nil
	case []any:
		result := make([]any, len(value))
		for i, item := range value {
			encoded, err := Tagged(item)
			if err != nil {
				return nil, fmt.Errorf("encode array item %d: %w", i, err)
			}
			result[i] = encoded
		}
		return result, nil
	default:
		return nil, fmt.Errorf("unsupported TOML value %T", v)
	}
}

// MarshalJSON encodes a Value as the required tagged JSON scalar.
func (v Value) MarshalJSON() ([]byte, error) {
	return json.Marshal(struct {
		Type  Kind   `json:"type"`
		Value string `json:"value"`
	}{v.Kind, v.Lexeme})
}
