func assignmentEquals(s string) (int, error) {
	quote := byte(0)
	depth := 0
	for i, c := range []byte(s) {
		if quote != 0 {
			if c == quote && (i == 0 || s[i-1] != '\\') {
				quote = 0
			}
			continue
		}
		if c == '"' || c == '\'' {
			quote = c
		}
		if c == '[' || c == '{' {
			depth++
		}
		if c == ']' || c == '}' {
			depth--
		}
		if c == '=' && depth == 0 {
			return i, nil
		}
	}
	return 0, fmt.Errorf("expected key/value pair")
}

func parseKey(s string) ([]string, error) {
	var keys []string
	for {
		s = strings.TrimSpace(s)
		if s == "" {
			return nil, fmt.Errorf("empty key")
		}
		var key string
		if s[0] == '"' || s[0] == '\'' {
			q := s[0]
			end := 1
			for end < len(s) {
				if s[end] == q && (q == '\'' || !escapedAt(s, end)) {
					break
				}
				end++
			}
			if end == len(s) {
				return nil, fmt.Errorf("unterminated key")
			}
			raw := s[:end+1]
			if q == '"' {
				var err error
				raw, err = unquote(raw)
				if err != nil {
					return nil, err
				}
			} else {
				raw = raw[1:end]
				if strings.ContainsAny(raw, "\r\n") {
					return nil, fmt.Errorf("newline in key")
				}
			}
			key, s = raw, s[end+1:]
		} else {
			end := strings.IndexByte(s, '.')
			if end < 0 {
				end = len(s)
			}
			key, s = strings.TrimSpace(s[:end]), s[end:]
			if key == "" {
				return nil, fmt.Errorf("invalid key")
			}
			for _, r := range key {
				if !(r == '_' || r == '-' || r >= 'a' && r <= 'z' || r >= 'A' && r <= 'Z' || r >= '0' && r <= '9') {
					return nil, fmt.Errorf("invalid bare key")
				}
			}
		}
		keys = append(keys, key)
		s = strings.TrimSpace(s)
		if s == "" {
			return keys, nil
		}
		if s[0] != '.' {
			return nil, fmt.Errorf("invalid dotted key")
		}
		s = s[1:]
	}
}

func ensureParent(root Object, path []string) (Object, string, error) {
	if len(path) == 0 {
		return nil, "", fmt.Errorf("empty table")
	}
	obj := root
	for _, p := range path[:len(path)-1] {
		if x, ok := obj[p].(Object); ok {
			obj = x
		} else if obj[p] == nil {
			x := Object{}
			obj[p] = x
			obj = x
		} else {
			return nil, "", fmt.Errorf("table conflict")
		}
	}
	return obj, path[len(path)-1], nil
}
func ensureTable(root Object, path []string, decl map[string]bool) (Object, error) {
	obj := root
	for i, p := range path {
		if x, ok := obj[p].(Object); ok {
			obj = x
			continue
		}
		if arr, ok := obj[p].([]any); ok && len(arr) > 0 {
			if x, ok := arr[len(arr)-1].(Object); ok {
				obj = x
				continue
			}
		}
		if obj[p] != nil {
			return nil, fmt.Errorf("table conflict")
		}
		x := Object{}
		obj[p] = x
		obj = x
		_ = i
	}
	name := strings.Join(path, ".")
	if decl[name] && !hasArrayAncestor(root, path) {
		return nil, fmt.Errorf("table redefinition")
	}
	decl[name] = true
	return obj, nil
}

func hasArrayAncestor(root Object, path []string) bool {
	obj := root
	for _, part := range path[:len(path)-1] {
		if arr, ok := obj[part].([]any); ok {
			return len(arr) > 0
		}
		x, ok := obj[part].(Object)
		if !ok {
			return false
		}
		obj = x
	}
	return false
}

func parseValue(s string) (any, error) {
	s = strings.TrimSpace(s)
	if s == "true" || s == "false" {
		return Value{Bool, s}, nil
	}
	if len(s) >= 2 && (s[0] == '"' || s[0] == '\'') {
		return parseString(s)
